+
+// A per-line discount: percent off one sku's line total.
+export function lineDiscountCents(line, percent) {
+  if (!Number.isInteger(percent) || percent < 0 || percent > 100) throw new RangeError(`percent must be 0..100: ${percent}`);
+  return Math.round((line.unitCents * line.quantity * percent) / 100);
